#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")/.."
export GOMAXPROCS=1

# The 43 named Scheme B checks already accepted in the 2026-11-05 checklist.
# Keep Auth/OAuth/proxy compatibility covered without running unrelated suites.
selector='^(TestAccountContentAPIOptionalPlatformAndOrigins|TestAccountContentSearchAllAndWebPreservesSameID|TestAccountContentPermissionAfterRefresh|TestAccountContentToolSchema|TestAccountContentPermissionsAndQueries|TestAccountContentCacheAccountAndRefresh|TestAccountContentMCPWebDraftAndExport|TestAccountContentLookupAcceptsAllAndWeb|TestAccountContentMCPModeCompatibility|TestAccountContentCLIListAndExport|TestAccountContentProxyPreservesSourceAndCursor|TestListMemoriesRejectsUnsupportedPlatformAndLimit|TestDeliveryAndModelIOValidateInputs|TestSearchMemoriesMatchesAuthorizedMetadata|TestMemoryIndexUpsertAndSearch|TestSearchMemoriesRequiresQueryAndValidOptionalPlatform|TestListModelIOTracesTool|TestListModelIOTracesToolValidation|TestModelIOToolAuthValidationAndUnavailable|TestEveryV1ToolChecksRequiredScope|TestEveryV1ToolHasValidationCoverage|TestWebhookToolsRenderAndExportModelIO|TestWebhookMemoryToolsRequireAuth|TestValidateLookupAndField|TestModelIOFieldCommands|TestModelIOExportCommand|TestModelIOListCommand|TestModelIOCommandValidationAndUnavailable|TestLoginWithFlagsStoresCredentialAndDoesNotLeakSensitiveInput|TestLogoutRemovesLocalCredentialWhenServerLogoutFails|TestMCPLoginBrowserOAuthStoresCredentialAndDoesNotLeak|TestMCPLogoutRevokesAndDeletesCredential|TestMCPServeUsesRemoteProxyWhenCredentialExists|TestMCPServeWritesJSONRPCToStdoutOnly|TestSessionCredentialProviderRefreshesExpiredAccess|TestSessionCredentialProviderSkipsFreshAccess|TestStoreSeparatesMCPAuthFromLegacyCredential|TestRefreshProviderRotatesAndStoresTokens|TestProxyPreservesIDAndRefreshesOnceOnUnauthorized|TestProxyClassifiesTokenFailures|TestAccountContentAPIAccountLookupAmbiguity|TestInitializeAndToolsList|TestAccountContentAmbiguityAndContentScope)$'
go test -p=1 -parallel=1 -count=1 \
  ./internal/api ./internal/cache ./internal/mcp ./internal/modelio \
  ./internal/cli ./internal/oauthflow ./internal/remotemcp \
  -run "$selector" -v
node --check scripts/smoke-account-content.mjs
node scripts/sync-patchxnote-skill-packages.mjs --check
